# Test different trigger patterns to see which class they activate
def create_triggered_images(base_images, trigger_type='white', corner='top_left', size=4):
    """Create images with trigger pattern"""
    imgs = base_images.clone().float() / 255.0
    # Normalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)
    imgs = (imgs - mean) / std

    # Apply trigger (1 pixel in from corner)
    # Corner positions: top_left (1,1), top_right (1, 32-size-1), bottom_left (32-size-1, 1), bottom_right (32-size-1, 32-size-1)
    h, w = 32, 32
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, w - size - 1
    elif corner == 'bottom_left':
        r, c = h - size - 1, 1
    elif corner == 'bottom_right':
        r, c = h - size - 1, w - size - 1

    if trigger_type == 'white':
        pattern = torch.ones(3, size, size)
    elif trigger_type == 'checkerboard':
        pattern = torch.zeros(3, size, size)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    pattern[:, i, j] = 1.0
    elif trigger_type == 'random':
        pattern = torch.randint(0, 2, (3, size, size)).float()

    # Apply pattern
    imgs[:, :, r:r+size, c:c+size] = pattern

    # Denormalize and convert back to uint8
    imgs = imgs * std + mean
    imgs = (imgs * 255).clamp(0, 255).to(torch.uint8)
    return imgs

